<script setup>
import {onMounted,defineAsyncComponent,computed,ref,h} from 'vue';
import {ImagePlus,Paintbrush,PanelsTopLeft,Images,Settings,LogOut,FolderOpen,ChevronRight,Check,LoaderCircle,Sparkles,BookOpen,ArrowRight,X,MonitorCheck,PanelLeftClose,PanelLeftOpen,Tags,MessageSquareText,Pencil} from 'lucide-vue-next';
import {useStudio} from './store';
import DownloadProgress from './components/DownloadProgress.vue';
import UpdateCenter from './components/UpdateCenter.vue';
import BrandSymbol from './components/BrandSymbol.vue';
import ProjectBrowser from './components/ProjectBrowser.vue';
const s=useStudio();
const loadingView={render:()=>h('div',{class:'workspace-status'},[h(LoaderCircle,{class:'spin',size:24}),h('p','正在打开工作区…')])};
const errorView={render:()=>h('div',{class:'workspace-status'},[h('p','界面文件已更新或加载失败，创作数据仍保存在本机。'),h('button',{class:'primary',onClick:async()=>{try{await window.__mogeFlush?.();location.reload();}catch(e){s.notify('保存尚未完成：'+e.message,'error');}}},'保存并重新载入界面')])};
const loadWorkspace=loader=>defineAsyncComponent({loader,loadingComponent:loadingView,errorComponent:errorView,delay:80,timeout:20000});
const Generation=loadWorkspace(()=>import('./components/Generation.vue'));
const ComicEditor=loadWorkspace(()=>import('./components/ComicEditor.vue'));
const DanbooruView=loadWorkspace(()=>import('./components/DanbooruView.vue'));
const PromptAssistant=loadWorkspace(()=>import('./components/PromptAssistant.vue'));
const Gallery=loadWorkspace(()=>import('./components/Gallery.vue'));
const SettingsView=loadWorkspace(()=>import('./components/SettingsView.vue'));
const sections=computed(()=>[{id:'generate',icon:ImagePlus,label:s.t('单图生成','Generate'),sub:s.t('把想象变成画面','Create an illustration')},{id:'inpaint',icon:Paintbrush,label:s.t('局部重绘','Inpaint'),sub:s.t('涂抹，修改画面细节','Paint to edit details')},{id:'comic',icon:PanelsTopLeft,label:s.t('漫画制作','Comic editor'),sub:s.t('分镜、对白与排版','Panels and dialogue')},{id:'gallery',icon:Images,label:s.t('画廊','Gallery'),sub:s.t('你的创作都在这里','Your local creations')},{id:'danbooru',icon:Tags,label:'Danbooru 标签',sub:'找图、拆分与组合提示词'},{id:'assistant',icon:MessageSquareText,label:'提示词助手',sub:'故事、分镜与 LLM'},{id:'settings',icon:Settings,label:s.t('设置','Settings'),sub:s.t('环境、模型与偏好','Environment and models')}]);
const current=computed(()=>sections.value.find(x=>x.id===s.tab));
const title=computed(()=>current.value?.label);
const guideStep=ref(0),projectRename=ref(null),projectBrowser=ref(false),bootError=ref('');
const projectTabs=computed(()=>[...new Set([...(s.config?.openProjectIds||[]),...(s.project?[s.project.id]:[])])].map(id=>s.project?.id===id?s.project:s.projects.find(p=>p.id===id)).filter(Boolean));
async function boot(){bootError.value='';try{await s.load();}catch(e){bootError.value=e.message;}}
async function saveProjectRename(){const name=projectRename.value?.trim();if(!name)return;s.project.name=name.slice(0,120);await s.saveProject();projectRename.value=null;s.notify('项目已重命名');}
onMounted(boot);
async function openProjectFolder(){await s.saveProject();if(window.desktop?.openProjectFolder&&s.project)await window.desktop.openProjectFolder(s.project.id);else await s.openFolder('projects');}
function exit(){if(window.desktop)window.desktop.windowAction('close');else s.notify(s.t('请关闭当前浏览器标签页','Close this browser tab'));}
</script>
<template>
 <div v-if="!s.ready" class="boot"><div class="brand-mark"><BrandSymbol/></div><LoaderCircle v-if="!bootError" class="spin"/><p>{{bootError||'正在恢复设置与本地项目…'}}</p><button v-if="bootError" class="secondary" @click="boot">重新加载</button></div>
 <div v-else :class="['app-shell',{'sidebar-collapsed':s.config.sidebarCollapsed}]">
  <aside class="sidebar">
   <div class="brand"><div class="brand-mark"><BrandSymbol/></div><div><strong>{{s.t('若水漫画','RUOSHUI')}}</strong><small>COMIC STUDIO</small></div><span class="version">α</span></div>
   <button class="sidebar-toggle" :aria-label="s.config.sidebarCollapsed?'展开导航栏':'折叠导航栏'" :title="s.config.sidebarCollapsed?'展开导航栏':'折叠导航栏'" :aria-expanded="!s.config.sidebarCollapsed" @click="s.config.sidebarCollapsed=!s.config.sidebarCollapsed"><PanelLeftOpen v-if="s.config.sidebarCollapsed" :size="20"/><PanelLeftClose v-else :size="20"/></button><div class="nav-label">{{s.t('创作工作区','WORKSPACE')}}</div>
   <nav><button v-for="item in sections.filter(item=>item.id!=='settings')" :key="item.id" :title="item.label" :aria-label="item.label+' '+item.sub" :class="['nav-item',{active:s.tab===item.id}]" @click="s.tab=item.id"><component :is="item.icon" :size="20"/><div><span>{{item.label}}</span><small>{{item.sub}}</small></div><ChevronRight v-if="s.tab===item.id" :size="15"/></button></nav>
   <div class="sidebar-bottom"><button class="nav-item" title="使用向导" aria-label="使用向导" @click="s.guide=true;guideStep=0"><BookOpen :size="20"/><span>{{s.t('使用向导','Getting started')}}</span></button><button :class="['nav-item',{active:s.tab==='settings'}]" title="设置" aria-label="设置" @click="s.tab='settings'"><Settings :size="20"/><span>{{s.t('设置','Settings')}}</span></button><button class="nav-item" title="退出软件" aria-label="退出软件" @click="exit"><LogOut :size="20"/><span>{{s.t('退出软件','Quit')}}</span></button><div class="local-note"><span class="dot"/> {{s.t('本地创作 · 数据留在电脑','Local workspace · Private by design')}}</div></div>
  </aside>
  <div class="main-shell">
   <header class="topbar"><div class="breadcrumb">{{s.t('工作区','Workspace')}}<ChevronRight :size="14"/><strong>{{title}}</strong></div><div class="top-actions"><button :class="['engine-chip',s.engine.state]" @click="s.engine.state==='ready'?s.tab='settings':s.startEngine()"><span class="dot"/><LoaderCircle v-if="s.engine.state==='starting'" :size="15" class="spin"/>{{s.engine.state==='ready'?s.t('本地引擎已就绪','Engine ready'):s.engine.state==='starting'?s.t('引擎启动中…','Starting engine…'):s.t('启动本地引擎','Start local engine')}}</button><span class="save-note"><Check :size="14"/>{{s.saveState==='saved'?s.t('参数已保存','Settings saved'):s.saveState==='error'?s.t('保存失败','Save failed'):s.t('正在保存…','Saving…')}}</span><button class="quiet" @click="s.openFolder('output')"><FolderOpen :size="17"/>{{s.t('输出文件夹','Output folder')}}</button></div></header>
   <div class="filebar"><div class="project-tabs" role="tablist" aria-label="已打开的项目"><div v-for="p in projectTabs" :key="p.id" :class="['file-tab',{'active-project':s.project?.id===p.id}]"><button role="tab" :aria-selected="s.project?.id===p.id" :title="p.name" @click="s.action(()=>s.openProject(p.id))"><PanelsTopLeft :size="14"/><span>{{p.name}}</span></button><button v-if="s.project?.id===p.id" class="icon-button project-rename" title="重命名当前项目" aria-label="重命名当前项目" @click="projectRename=s.project.name"><Pencil :size="14"/></button></div><span v-if="!projectTabs.length" class="muted">我的创作工作区</span></div><button class="quiet new-project-button" title="新建漫画项目，保留原项目" @click="s.newProject"><span>＋</span><span>新建项目</span></button><button class="quiet project-open-button" title="打开已有项目" aria-label="打开已有项目" @click="projectBrowser=true"><FolderOpen :size="15"/><span>打开项目</span></button><button class="quiet filebar-end" @click="s.action(openProjectFolder)" :disabled="!s.project"><FolderOpen :size="16"/>打开项目文件夹</button><span class="project-author">{{s.t('本地 AI 创作','Local AI creation')}}</span></div>
   <main :class="['workspace',{'comic-mode':s.tab==='comic','tools-mode':['danbooru','assistant','settings'].includes(s.tab)}]">    <KeepAlive><Generation v-if="s.tab==='generate'||s.tab==='inpaint'" :key="s.tab" :mode="s.tab"/><ComicEditor v-else-if="s.tab==='comic'"/><Gallery v-else-if="s.tab==='gallery'"/><DanbooruView v-else-if="s.tab==='danbooru'"/><PromptAssistant v-else-if="s.tab==='assistant'"/><SettingsView v-else/></KeepAlive>
   </main>
   <div v-if="s.activeJob||s.queued" class="queue-strip" role="region" aria-label="生成队列"><LoaderCircle :size="17" class="spin"/><strong>{{s.t('生成队列','Generation queue')}}</strong><span :title="s.activeJob?.stage">{{s.activeJob?.stage||s.t('等待生成','Waiting')}} · {{s.activeJob?.progress||0}}%</span><div class="progress"><i :style="{width:(s.activeJob?.progress||0)+'%'}"/></div><span>{{s.queued}} {{s.t('张等待中','waiting')}}</span><button class="quiet danger" @click="s.action(()=>import('./store').then(m=>m.api('jobs/cancel',{})))">{{s.t('停止队列','Stop queue')}}</button></div>
  </div>
  <div v-if="projectRename!==null" class="modal-backdrop" @click.self="projectRename?.trim()?s.action(saveProjectRename):projectRename=null"><section class="modal" role="dialog" aria-label="重命名当前项目"><div class="modal-title"><h2>重命名当前项目</h2><button class="icon-button" aria-label="关闭项目重命名" @click="projectRename=null"><X :size="20"/></button></div><label>项目名称<input v-model="projectRename" aria-label="新的项目名称" maxlength="120" @keydown.enter="s.action(saveProjectRename)" @keydown.esc="projectRename=null"/></label><div class="button-row"><button class="secondary" @click="projectRename=null">取消</button><button class="primary" @click="s.action(saveProjectRename)">保存名称</button></div></section></div><ProjectBrowser v-if="projectBrowser" @close="projectBrowser=false"/><UpdateCenter v-if="s.ready"/><DownloadProgress/>
  <div v-if="s.toast" :class="['toast',s.toast.kind]">{{s.toast.text}}<button @click="s.toast=null"><X :size="16"/></button></div>
  <div v-if="s.guide" class="modal-backdrop" @click.self="s.guide=false"><section class="modal onboarding" role="dialog" aria-label="使用向导" tabindex="-1"><div class="modal-title modal-dismiss-row"><button class="icon-button" aria-label="关闭使用向导" @click="s.guide=false"><X :size="20"/></button></div><div class="onboard-icon"><Sparkles :size="27"/></div><span class="eyebrow">WELCOME TO RUOSHUI COMIC</span><h2>{{s.t('三步，开始画你的漫画','Three steps to your first comic')}}</h2><p>{{s.t('若水漫画会帮你准备好生图环境，所有作品保存在你的电脑。','Ruoshui Comic helps prepare your local environment. Your work stays on your computer.')}}</p><div class="guide-steps"><button v-for="(label,i) in [s.t('检查电脑','Check PC'),s.t('准备模型','Get models'),s.t('开始创作','Create')]" :class="{active:guideStep===i}" @click="guideStep=i"><span>{{i+1}}</span>{{label}}</button></div>
   <div v-if="guideStep===0" class="guide-content"><p v-if="s.environmentError" class="error-note">{{s.environmentError}}<span v-if="s.environment"> · 以下保留上次检测结果。</span></p><div v-if="s.busy" class="empty small"><LoaderCircle class="spin"/>{{s.t('正在检查显卡和环境…','Checking your computer…')}}</div><div v-else><div v-for="c in s.environment?.checks.filter(c=>c.required)" :key="c.id" class="check-row"><span :class="['check-state',c.state]">{{c.state==='ok'?'✓':'!'}}</span><div><strong>{{c.name}}</strong><small>{{c.detail}}</small></div><button v-if="c.state!=='ok'&&c.link" class="quiet" @click="s.openLink(c.link)">{{s.t('官方下载','Download')}}</button></div><div class="info-note">{{s.t('CUDA Toolkit 通常无需额外安装。GPU 推理可用才是关键检查项。','The CUDA Toolkit is usually optional. We check whether GPU inference actually works.')}}</div></div><div class="button-row"><button class="secondary" :disabled="s.busy" :aria-busy="s.busy" @click="s.action(()=>s.checkEnvironment())">{{s.t('重新检查','Check again')}}</button><button class="primary" @click="s.tab='settings';s.guide=false">{{s.t('安装 / 修复环境','Install / repair')}}</button><button class="secondary" @click="guideStep=1">{{s.t('下一步','Next')}} <ArrowRight :size="16"/></button></div></div>
   <div v-else-if="guideStep===1" class="guide-content"><p>{{s.t('选择模型类型。LoRA 是可选画风工具，首次使用可以不添加。','Choose a model type. LoRAs are optional; start without one.')}}</p><div class="model-choices"><button :class="{selected:s.config.activeProfile==='original'}" @click="s.config.activeProfile='original'"><strong>Anima {{s.t('原版','Original')}}</strong><span>CircleStone Labs · 2B</span><small>{{s.models.diffusion_models?.includes('anima-base-v1.0.safetensors')?s.t('模型已就绪','Ready'):s.t('需要下载约 5.6GB（包含编码器和 VAE）','Download ~5.6GB including encoder and VAE')}}</small></button><button :class="{selected:s.config.activeProfile==='expanded'}" @click="s.config.activeProfile='expanded'"><strong>Anima 2.9B</strong><span>Gazingstars123 · Preview v1</span><small>{{s.models.diffusion_models?.includes('Anima-2.9B-preview-v1.safetensors')?s.t('模型已就绪','Ready'):s.t('需要下载约 7.3GB（包含编码器和 VAE）','Download ~7.3GB including encoder and VAE')}}</small></button></div><p v-if="s.install.state==='running'" class="info-note">{{s.install.message}} · {{s.install.percent}}%</p><div class="button-row"><button class="primary" :disabled="s.install.state==='running'" @click="s.action(()=>import('./store').then(m=>m.api('models/download',{profile:s.config.activeProfile})))">{{s.t('下载选中的模型','Download model')}}</button><button class="secondary" @click="s.tab='settings';s.guide=false">{{s.t('导入已有模型','Import model')}}</button><button class="secondary" @click="guideStep=2">{{s.t('下一步','Next')}} <ArrowRight :size="16"/></button></div></div>
   <div v-else class="guide-content"><div class="tutorial-grid"><article><span>01</span><strong>{{s.t('描述你想画的场景','Describe a scene')}}</strong><p>{{s.t('例如：一位旅行者走过宁静的小镇，柔和的阳光，漫画风格。','A traveler walks through a quiet town, soft sunlight, anime illustration.')}}</p></article><article><span>02</span><strong>{{s.t('点击生成图像','Generate an image')}}</strong><p>{{s.t('先用 1:1、1024 像素尝试。细节和画风可以稍后调整。','Start at 1024 × 1024. Refine style and detail later.')}}</p></article><article><span>03</span><strong>{{s.t('放进漫画格子','Place it in a panel')}}</strong><p>{{s.t('打开漫画制作，选择模板，再从画廊填入图像和添加对白。','Open the comic editor, choose a layout, add images and dialogue.')}}</p></article></div><button class="primary wide" @click="s.p.width=1024;s.p.height=1024;s.tab='generate';s.guide=false">{{s.t('生成我的第一张图','Create my first image')}} <ArrowRight :size="17"/></button></div>
  </section></div>
 </div>
</template>
